/* Size charts for physical products (round BC): a store keeps its size tables in size_charts (a name, the unit the numbers were typed in, cm or in, its columns as a list of {name, measure}, its rows as a list of lists of text, an optional note and picture), and product_size_charts says which chart a product shows, one row per product that has one (a chart serves many products; deleting a chart or a product takes its links with it). Read by the product page on a Storelib theme (the Size chart block and the Size guide link beside the size option) and on an imported Shopify theme (product.metafields.storelib.size_chart, an app block and a link beside the size), and written by Products > Size charts and the product editor's Size chart card through /api/size-charts. Row level security on both: visitors (anon) are granted nothing, a signed in owner reads their own, and only the server writes, after its owner checks; the storefront reads through the server. Before it runs the product editor says size charts need this part and every product page simply has no chart. Additive: nothing is dropped, renamed or changed. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.size_charts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, name text NOT NULL, unit text NOT NULL DEFAULT 'cm', columns jsonb NOT NULL DEFAULT '[]'::jsonb, rows jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, image_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT size_charts_name_len CHECK (char_length(btrim(name)) BETWEEN 1 AND 80), CONSTRAINT size_charts_unit CHECK (unit IN ('cm', 'in')), CONSTRAINT size_charts_columns_list CHECK (jsonb_typeof(columns) = 'array' AND jsonb_array_length(columns) BETWEEN 1 AND 10), CONSTRAINT size_charts_rows_list CHECK (jsonb_typeof(rows) = 'array' AND jsonb_array_length(rows) <= 40), CONSTRAINT size_charts_notes_len CHECK (notes IS NULL OR char_length(notes) <= 1500), CONSTRAINT size_charts_image_len CHECK (image_url IS NULL OR char_length(image_url) <= 2048), CONSTRAINT size_charts_size CHECK (pg_column_size(rows) < 65536));
CREATE INDEX IF NOT EXISTS size_charts_creator_idx ON public.size_charts (creator_id, name);
CREATE TABLE IF NOT EXISTS public.product_size_charts (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, size_chart_id uuid NOT NULL REFERENCES public.size_charts(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_size_charts_chart_idx ON public.product_size_charts (size_chart_id);
CREATE INDEX IF NOT EXISTS product_size_charts_creator_idx ON public.product_size_charts (creator_id);
DO $do$ BEGIN IF to_regprocedure('public.update_updated_at_column()') IS NULL THEN CREATE FUNCTION public.update_updated_at_column() RETURNS trigger LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END $fn$; END IF; DROP TRIGGER IF EXISTS size_charts_touch ON public.size_charts; CREATE TRIGGER size_charts_touch BEFORE UPDATE ON public.size_charts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); END $do$;
ALTER TABLE public.size_charts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_size_charts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.size_charts, public.product_size_charts FROM PUBLIC, anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.size_charts, public.product_size_charts FROM authenticated;
GRANT SELECT ON public.size_charts, public.product_size_charts TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.size_charts, public.product_size_charts TO service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads size_charts" ON public.size_charts; CREATE POLICY "storelib owner reads size_charts" ON public.size_charts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = size_charts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib owner reads product_size_charts" ON public.product_size_charts; CREATE POLICY "storelib owner reads product_size_charts" ON public.product_size_charts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.creators c WHERE c.id = product_size_charts.creator_id AND c.user_id = (SELECT auth.uid()))); END $do$;
notify pgrst, 'reload schema';
